/*
 * VRCW — i18n.js
 * 独立 i18n 字典 + 运行时(t / setLang / applyI18n)
 *
 * 加载顺序:必须在 core.js 之后(经典脚本 <script defer> 按顺序加载,共享全局)。
 * 依赖 core.js 声明的 `currentLang`(let,在 core.js L61)。
 * 其他脚本(common.js 的 DOMContentLoaded→setLang)依赖此处定义的函数。
 */

