// ── 翻訳関数(支持插值) ──
// t('toast.reported', {name: 'Alice'}) → "已举报 Alice"
// 占位符语法:{key}
function t(key, params) {
  let s = (I18N[currentLang] || I18N.en)[key] || I18N.en[key] || key;
  if (params && typeof s === 'string') {
    for (const k in params) {
      s = s.split(`{${k}}`).join(params[k] == null ? '' : params[k]);
    }
  }
  return s;
}

// ── 切换语言 ──
function setLang(lang) {
  currentLang = lang;
  localStorage.setItem("vrc_lang", lang);
  applyI18n();

  // Update <html lang> so screen readers, search engines and browser
  // translation features know which language the page actually uses.
  // (Static lang="zh" was just the initial default.)
  const htmlLangMap = { en: 'en', zh: 'zh-CN', ja: 'ja' };
  if (htmlLangMap[lang]) document.documentElement.lang = htmlLangMap[lang];

  document.querySelectorAll(".lang-btn").forEach((b) =>
    b.classList.toggle(
      "active",
      b.textContent.trim() ===
        ({ en: "EN", zh: "中文", ja: "日本語" }[lang] || "")
    )
  );
}

// ── DOM 扫描应用 i18n ──
// 支持:
//   data-i18n             → textContent
//   data-i18n-placeholder → placeholder 属性
//   data-i18n-title       → title 属性
//   data-i18n-html        → innerHTML(用于含 <i> 图标的文本)
function applyI18n(root = document) {
  root.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const val = t(key);
    if (val) el.textContent = val;
  });
  root.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const key = el.getAttribute("data-i18n-placeholder");
    const val = t(key);
    if (val) el.placeholder = val;
  });
  root.querySelectorAll("[data-i18n-title]").forEach((el) => {
    const key = el.getAttribute("data-i18n-title");
    const val = t(key);
    if (val) el.title = val;
  });
  root.querySelectorAll("[data-i18n-html]").forEach((el) => {
    const key = el.getAttribute("data-i18n-html");
    const val = t(key);
    if (val) el.innerHTML = val;
  });
}
